#ifndef PARTICLEBASE_H
#define PARTICLEBASE_H

#include <vector>
#include "IPPLException.h"
#include "Types.h"

namespace IPPL {

class ParticleBase {
public:
    virtual ~ParticleBase() {}

    // Add a particle to the container
    void addParticle(const Particle& p) {
        m_particles.push_back(p);
    }

    // Get the number of particles
    size_t getNumParticles() const {
        return m_particles.size();
    }

    // Get a specific particle by index
    Particle& getParticle(size_t idx) {
        if (idx >= m_particles.size()) {
            throw IPPLException("Index out of range in ParticleBase::getParticle");
        }
        return m_particles[idx];
    }

    const Particle& getParticle(size_t idx) const {
        if (idx >= m_particles.size()) {
            throw IPPLException("Index out of range in ParticleBase::getParticle (const)");
        }
        return m_particles[idx];
    }

protected:
    std::vector<Particle> m_particles;
};

}  // namespace IPPL
```

---

