// boundary_conditions.cpp

#include "boundary_conditions.h"
#include "field.h"

DirichletBoundaryCondition::DirichletBoundaryCondition(double value) : value_(value) {}

void DirichletBoundaryCondition::apply(Field& field) {
    // Apply Dirichlet boundary condition to the field
    for (int i = 0; i < field.size(); ++i) {
        if (field.is_boundary(i)) {
            field.set_value(i, value_);
        }
    }
}

