void DepositCharge(Grid& grid, const Particles& particles) {
    // Loop over all particles and deposit their charge onto the grid.
    for (const auto& particle : particles) {
        if (!grid.InBounds(particle.GetPosition())) continue;

        // Determine which deposition method to use based on configuration.
        switch (Config::charge_deposition_method) {
