#include "random/normal.h"
#include <cmath>
#include <cstdlib>

namespace ippl {

double Normal::operator()(double mean, double stddev) {
    // Box-Muller transform to generate a normal distribution sample
    double u1 = this->next();
    double u2 = this->next();

    double z0 = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);
    // We could use the second sample (z1) for another independent normal variable
    return mean + stddev * z0;
}

}  // namespace ippl
```

