#include "IpplTimings.h"
#include <iostream>
#include <chrono>

IpplTimings::IpplTimings() {}

IpplTimings::~IpplTimings() {
    printAll();
}

void IpplTimings::start(const std::string& regionName) {
    _timings[regionName] = std::chrono::high_resolution_clock::now().time_since_epoch().count();
}

void IpplTimings::stop(const std::string& regionName) {
    double endTime = std::chrono::high_resolution_clock::now().time_since_epoch().count();
    if (_timings.find(regionName) != _timings.end()) {
        double duration = (endTime - _timings[regionName]) / 1e9; // Convert to seconds
        std::cout << "Region: " << regionName << " took " << duration << " seconds" << std::endl;
    } else {
        std::cerr << "Error: Region " << regionName << " not started." << std::endl;
    }
}

void IpplTimings::printAll() const {
    for (const auto& pair : _timings) {
        std::cout << "Region: " << pair.first << " took " << pair.second / 1e9 << " seconds" << std::endl;
    }
}
```

